    The function should return True if and only if there is a valid subsequence of brackets 
    where at least one bracket in the subsequence is nested.

    is_nested('[[]]') ➞ True
    is_nested('[]]]]]]][[[[[]') ➞ False
    is_nested('[][]') ➞ False
    is_nested('[]') ➞ False
    is_nested('[[][]]') ➞ True
    is_nested('[[]][[') ➞ True
    """

    def is_valid(subsequence):
        if not subsequence:
            return False
        for i in range(len(subsequence) - 1, -1, -1):
          if subsequence[i] == '[' or subsequence[i] == ']':
              return True
        return False

    def solve(s):
      n = len(s)
      if n <= 0:
         return False
      for i in range(n):
           if s[i] == '[':
               if is_valid(s[:i+1]):
                   return True
              else:
                 continue

    return solve(string) or is_nested('[]]')
