def largest_smallest_integers(lst):
    """
    Create a function that returns a tuple (a, b), where 'a' is
    the largest of negative integers, and 'b' is the smallest
    of positive integers in a list.
    If there is no negative or positive integers, return them as None.

    Examples:
    largest_smallest_integers([2, 4, 1, 3, 5, 7]) == (None, 1)
    largest_smallest_integers([]) == (None, None)
    largest_smallest_integers([0]) == (None, None)
    """

    negativeNumbers = []
    positiveNumbers = []

    for num in lst:
        if num < 0:
            negativeNumbers.append(num)
        elif num > 0:
             positiveNumbers.append(num)

    if not negativeNumbers and not positiveNumbers:
      return (None, None)

    if not negativeNumbers:
       return (None, None)

    largest = max(negativeNumbers) if negativeNumbers else -float('inf')
    smallest = min(positiveNumbers) if positiveNumbers else float('-inf')

    return (largest, smallest)
